import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { fireEvent, render, screen } from "../../../test-utils/render";
import Scrubber from "../index";

const mockTrackRect = (track: Element) => {
  vi.spyOn(track, "getBoundingClientRect").mockReturnValue({
    bottom: 36,
    height: 36,
    left: 0,
    right: 200,
    toJSON: () => ({}),
    top: 0,
    width: 200,
    x: 0,
    y: 0,
  });
};

describe("Scrubber", () => {
  beforeEach(() => {
    if (!Element.prototype.setPointerCapture) {
      Element.prototype.setPointerCapture = vi.fn();
    }
    if (!Element.prototype.releasePointerCapture) {
      Element.prototype.releasePointerCapture = vi.fn();
    }
  });

  it("renders without throwing", () => {
    const { container } = render(<Scrubber />);
    expect(container).toBeInTheDocument();
  });

  it("renders the label and formatted value", () => {
    render(<Scrubber decimals={1} defaultValue={0.5} label="Opacity" />);

    expect(screen.getByText("Opacity")).toBeInTheDocument();
    expect(screen.getByText("0.5")).toBeInTheDocument();
  });

  it("drives the value via pointer drag and calls onValueChange", () => {
    const onValueChange = vi.fn();
    render(
      <Scrubber
        decimals={2}
        max={1}
        min={0}
        onValueChange={onValueChange}
        step={0.01}
      />
    );

    const track = screen.getByRole("slider");
    mockTrackRect(track);

    fireEvent.pointerDown(track, { clientX: 100, pointerId: 1 });
    expect(onValueChange).toHaveBeenCalledWith(0.5);

    fireEvent.pointerMove(track, { clientX: 200, pointerId: 1 });
    expect(onValueChange).toHaveBeenLastCalledWith(1);

    fireEvent.pointerUp(track, { pointerId: 1 });
    expect(track).toHaveAttribute("aria-valuenow", "1");
  });

  it("clamps the dragged value to min/max", () => {
    const onValueChange = vi.fn();
    render(
      <Scrubber max={1} min={0} onValueChange={onValueChange} step={0.01} />
    );

    const track = screen.getByRole("slider");
    mockTrackRect(track);

    fireEvent.pointerDown(track, { clientX: -50, pointerId: 1 });
    expect(onValueChange).toHaveBeenCalledWith(0);

    fireEvent.pointerMove(track, { clientX: 999, pointerId: 1 });
    expect(onValueChange).toHaveBeenLastCalledWith(1);
  });

  it("ignores pointer move while not dragging", () => {
    const onValueChange = vi.fn();
    render(<Scrubber onValueChange={onValueChange} />);

    const track = screen.getByRole("slider");
    mockTrackRect(track);

    fireEvent.pointerMove(track, { clientX: 100, pointerId: 1 });
    expect(onValueChange).not.toHaveBeenCalled();
  });

  it("does not update internal value when controlled", () => {
    const onValueChange = vi.fn();
    render(
      <Scrubber
        decimals={2}
        max={1}
        min={0}
        onValueChange={onValueChange}
        value={0.2}
      />
    );

    const track = screen.getByRole("slider");
    mockTrackRect(track);

    fireEvent.pointerDown(track, { clientX: 200, pointerId: 1 });
    expect(onValueChange).toHaveBeenCalledWith(1);
    // Controlled: displayed value stays at the prop value.
    expect(track).toHaveAttribute("aria-valuenow", "0.2");
  });

  it("adjusts the value with arrow keys", () => {
    const onValueChange = vi.fn();
    render(
      <Scrubber
        defaultValue={5}
        max={10}
        min={0}
        onValueChange={onValueChange}
        step={1}
      />
    );

    const track = screen.getByRole("slider");
    fireEvent.keyDown(track, { key: "ArrowRight" });
    expect(onValueChange).toHaveBeenLastCalledWith(6);

    fireEvent.keyDown(track, { key: "ArrowLeft" });
    expect(onValueChange).toHaveBeenLastCalledWith(5);

    fireEvent.keyDown(track, { key: "ArrowUp" });
    expect(onValueChange).toHaveBeenLastCalledWith(6);

    fireEvent.keyDown(track, { key: "ArrowDown" });
    expect(onValueChange).toHaveBeenLastCalledWith(5);
  });

  it("jumps to min/max with Home/End keys", () => {
    const onValueChange = vi.fn();
    render(
      <Scrubber
        defaultValue={0.5}
        max={1}
        min={0}
        onValueChange={onValueChange}
      />
    );

    const track = screen.getByRole("slider");
    fireEvent.keyDown(track, { key: "End" });
    expect(onValueChange).toHaveBeenLastCalledWith(1);

    fireEvent.keyDown(track, { key: "Home" });
    expect(onValueChange).toHaveBeenLastCalledWith(0);
  });

  it("ignores unrelated keys", () => {
    const onValueChange = vi.fn();
    render(<Scrubber defaultValue={0.5} onValueChange={onValueChange} />);

    const track = screen.getByRole("slider");
    fireEvent.keyDown(track, { key: "a" });
    expect(onValueChange).not.toHaveBeenCalled();
  });

  it("toggles hover state on mouse enter/leave", () => {
    render(<Scrubber />);

    const track = screen.getByRole("slider");
    fireEvent.mouseEnter(track);
    fireEvent.mouseLeave(track);

    expect(track).toBeInTheDocument();
  });

  it("renders tick marks based on the ticks prop", () => {
    const { container } = render(<Scrubber ticks={4} />);

    expect(container.querySelectorAll(".bg-foreground\\/25").length).toBe(4);
  });

  it("hides tick marks when ticks is 0", () => {
    const { container } = render(<Scrubber ticks={0} />);

    expect(container.querySelectorAll(".bg-foreground\\/25").length).toBe(0);
  });

  it("has no accessibility violations", async () => {
    const { container } = render(
      <Scrubber decimals={1} defaultValue={0.5} label="Opacity" />
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

export interface ScrubberProps {
  /** Additional CSS classes */
  className?: string;
  /** Number of decimal places to display */
  decimals?: number;
  /** Default value for uncontrolled usage */
  defaultValue?: number;
  /** Label displayed on the left side of the track */
  label?: string;
  /** Maximum value */
  max?: number;
  /** Minimum value */
  min?: number;
  /** Called when value changes during interaction */
  onValueChange?: (value: number) => void;
  /** Step increment */
  step?: number;
  /** Number of tick marks (0 to hide) */
  ticks?: number;
  /** Controlled value */
  value?: number;
}

const clamp = (val: number, min: number, max: number) =>
  Math.min(Math.max(val, min), max);

const roundToStep = (val: number, step: number, min: number) =>
  Math.round((val - min) / step) * step + min;

const Scrubber = ({
  label = "Value",
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = 0,
  max = 1,
  step = 0.01,
  decimals = 2,
  ticks = 9,
  className,
}: ScrubberProps) => {
  const shouldReduceMotion = useReducedMotion();
  const trackRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [isDragging, setIsDragging] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const [isHoverDevice, setIsHoverDevice] = useState(false);

  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : internalValue;
  const range = max - min;
  const percentage = range > 0 ? ((value - min) / range) * 100 : 0;
  const isActive = isDragging || (isHoverDevice && isHovering);

  useEffect(() => {
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsHoverDevice(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setIsHoverDevice(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const setValue = useCallback(
    (newValue: number) => {
      const clamped = clamp(roundToStep(newValue, step, min), min, max);
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onValueChange?.(clamped);
    },
    [step, min, max, isControlled, onValueChange]
  );

  const getValueFromPointer = useCallback(
    (clientX: number) => {
      const track = trackRef.current;
      if (!track) {
        return value;
      }
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      return min + ratio * range;
    },
    [min, range, value]
  );

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      trackRef.current?.setPointerCapture(e.pointerId);
      setIsDragging(true);
      setValue(getValueFromPointer(e.clientX));
    },
    [getValueFromPointer, setValue]
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) {
        return;
      }
      setValue(getValueFromPointer(e.clientX));
    },
    [isDragging, getValueFromPointer, setValue]
  );

  const handlePointerUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      let next: number | undefined;
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          next = value + step;
          break;
        case "ArrowLeft":
        case "ArrowDown":
          next = value - step;
          break;
        case "Home":
          next = min;
          break;
        case "End":
          next = max;
          break;
        default:
          return;
      }
      e.preventDefault();
      setValue(next);
    },
    [value, step, min, max, setValue]
  );

  const springConfig = shouldReduceMotion
    ? { duration: 0 }
    : { bounce: 0.1, duration: 0.25, type: "spring" as const };

  return (
    <div className={cn("relative w-full select-none", className)}>
      <div
        aria-label={label}
        aria-valuemax={max}
        aria-valuemin={min}
        aria-valuenow={Number(value.toFixed(decimals))}
        className="relative cursor-pointer overflow-hidden bg-muted outline-offset-2"
        onKeyDown={handleKeyDown}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={trackRef}
        role="slider"
        style={{
          borderRadius: 8,
          height: 36,
          touchAction: "none",
        }}
        tabIndex={0}
      >
        {/* Fill indicator */}
        <div
          className="pointer-events-none absolute inset-y-0 left-0 bg-foreground/14"
          style={{
            borderRadius: 8,
            transition: isDragging
              ? "none"
              : "width 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            width: `${percentage}%`,
          }}
        />

        {/* Tick marks */}
        {ticks > 0 && (
          <div className="pointer-events-none absolute inset-0">
            {Array.from({ length: ticks }, (_, i) => {
              const pos = ((i + 1) / (ticks + 1)) * 100;
              return (
                <div
                  className="absolute top-1/2 bg-foreground/25"
                  key={pos}
                  style={{
                    borderRadius: 999,
                    height: 6,
                    left: `${pos}%`,
                    transform: "translateX(-50%) translateY(-50%)",
                    width: 1,
                  }}
                />
              );
            })}
          </div>
        )}

        {/* Scrub bar (capsule thumb) */}
        <div
          className="pointer-events-none absolute"
          style={{
            left: `${percentage}%`,
            marginLeft: -5,
            top: "50%",
            transform: "translateX(-50%) translateY(-50%)",
            transition: isDragging
              ? "none"
              : "left 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            zIndex: 3,
          }}
        >
          <motion.div
            animate={{
              opacity: isActive ? 0.8 : 0.15,
              scaleX: isActive ? 1 : 0.7,
              scaleY: isActive ? 1 : 0.7,
            }}
            className="bg-foreground/90"
            style={{
              borderRadius: 999,
              height: 22,
              width: 4,
            }}
            transition={springConfig}
          />
        </div>

        {/* Label */}
        <div
          className="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 whitespace-nowrap text-foreground"
          style={{
            fontSize: 13,
            fontWeight: 500,
            zIndex: 4,
          }}
        >
          {label}
        </div>

        {/* Value display */}
        <div
          className="pointer-events-none absolute top-1/2 right-2.5 -translate-y-1/2 text-foreground"
