import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import { render, screen } from "../../../test-utils/render";
import Separator from "../index";
import RadixSeparator from "../separator.radix";

describe("Separator", () => {
  it("has no accessibility violations", async () => {
    const { container } = render(
      <div>
        <p>Above</p>
        <Separator />
        <p>Below</p>
      </div>
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("renders a semantic horizontal separator by default", () => {
    render(<Separator />);
    const sep = screen.getByRole("separator");
    expect(sep).toHaveAttribute("data-slot", "separator");
    expect(sep.className).toContain("bg-foreground/40");
    expect(sep.className).toContain("shrink-0");
  });

  it("supports vertical orientation", () => {
    render(<Separator orientation="vertical" />);
    expect(screen.getByRole("separator")).toHaveAttribute(
      "aria-orientation",
      "vertical"
    );
  });

  it("hides decorative separators from assistive tech", () => {
    const { container } = render(<Separator decorative />);
    expect(screen.queryByRole("separator")).toBeNull();
    expect(container.querySelector("[data-slot='separator']")).not.toBeNull();
  });
});

describe("Separator (Radix twin)", () => {
  it("has no accessibility violations", async () => {
    const { container } = render(
      <div>
        <p>Above</p>
        <RadixSeparator />
        <p>Below</p>
      </div>
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("supports vertical and decorative", () => {
    const { container } = render(
      <RadixSeparator decorative orientation="vertical" />
    );
    expect(screen.queryByRole("separator")).toBeNull();
    expect(container.querySelector("[data-slot='separator']")).not.toBeNull();
  });
});

"use client";

export type { SeparatorOrientation, SeparatorProps } from "./separator.base";
export { default } from "./separator.base";

"use client";

import { Separator as SeparatorPrimitive } from "@base-ui/react/separator";
import { cn } from "@repo/smoothui-utils";

export type SeparatorOrientation = "horizontal" | "vertical";

export interface SeparatorProps {
  /** Optional CSS class names */
  className?: string;
  /**
   * Purely visual divider. Hidden from assistive tech (`role="none"`).
   * Leave `false` when the line separates meaningful content groups.
   */
  decorative?: boolean;
  /** Layout direction of the line */
  orientation?: SeparatorOrientation;
}

/**
 * SmoothUI Separator — Base UI twin (default).
 * Thin 1px line; vertical separators stretch to the height of their flex row.
 */
export default function Separator({
  className,
  decorative = false,
  orientation = "horizontal",
}: SeparatorProps) {
  const a11yProps = decorative
    ? ({
        "aria-hidden": true,
        "aria-orientation": undefined,
        role: "none",
      } as const)
    : {};

  return (
    <SeparatorPrimitive
      {...a11yProps}
      className={cn(
        "shrink-0 bg-foreground/40",
        orientation === "horizontal" ? "h-px w-full" : "h-full min-h-4 w-px",
        className
      )}
      data-slot="separator"
      orientation={orientation}
    />
  );
}

